{
  "title": "The Glass Diver's Rescue",
  "gate_token": "T3oBhuSRdw9xFkhDoJqKOQ",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue team gathers at the ruined city gates.",
      "visual_description": "A pair of massive iron gates, rusted and ajar, overlook a desolate courtyard where tattered royal banners flap in the wind.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of a cursed tower ahead.",
      "visual_description": "The team stands before a twisted stone tower whose windows glow with an eerie green light; the lamp's flame flickers as it speaks.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "The sleeping tax collector blocks the path.",
      "visual_description": "A man in a dusty coat slumps against a ledger desk, his head resting on a stack of stamped papers, snoring softly in a narrow alley.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "Mara the Cartographer reads a faded map.",
      "visual_description": "Mara holds a brass compass over an ink-stained parchment, pointing toward a broken archway while the tin fox sniffs the ground.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The glass diver peers through a shattered mirror.",
      "visual_description": "Reflected in a cracked mirror propped against a wall, the glass diver sees a hidden corridor lined with ancient banners.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Armored patrols march past the hiding team.",
      "visual_description": "A squad of faceless metal figures clanks through the ruins, their armor scuffed and dented, as the team presses against a collapsed pillar.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "The tin fox scouts a magic door.",
      "visual_description": "A shimmering door of liquid silver stands in an archway, and the tiny fox circles it, its blue eyes reflecting the rippling surface.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Mara deciphers a riddle on the magic door.",
      "visual_description": "Mara traces glowing runes with her finger while the oracle lamp hovers nearby, casting a warm light over the inscriptions.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "The glass diver swims through a window into a sealed chamber.",
      "visual_description": "The diver presses against a grimy window, then passes through the glass into a dusty room filled with forgotten treasures.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "The team reunites after the glass diver opens the door from inside.",
      "visual_description": "The silver door dissolves as the glass diver turns a hidden crank; the others rush through into a moonlit courtyard.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "Frightened townspeople are huddled in a collapsed market.",
      "visual_description": "Clutching each other, a group of civilians in ragged clothes crouch behind overturned stalls, eyes wide at the approaching noise.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The oracle lamp guides them past a cursed well.",
      "visual_description": "A stone well with a chained bucket emits a faint blue mist; the lamp's flame burns brighter, steering the team away.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "The sleeping tax collector is found again, still asleep.",
      "visual_description": "He is curled up on a pile of stamped papers in a ruined treasury, a ledger under his head, oblivious to the search.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "The glass diver uses a window as a shortcut past a patrol.",
      "visual_description": "The diver leaps through a tall arched window, emerging silently behind the patrol while the others watch from a shadowed niche.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The tin fox triggers a trap but escapes.",
      "visual_description": "A pressure plate clicks, and a net of chains drops; the fox twists mid-air, its tail winding as it darts clear.",
      "characters": ["tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "The team finds a final magic door before the bridge.",
      "visual_description": "A door of polished obsidian stands at the edge of a plaza, its surface swirling with smoke; beyond it, the bridge is visible.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They open the door and race onto the bridge.",
      "visual_description": "The obsidian door swings open, and the team sprints across a long stone bridge that arches over a dark chasm, torches flickering along the railings.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge collapses behind them as they escape.",
      "visual_description": "The party reaches the far side, and the bridge crumbles into the chasm, the ruins of the city fading in the distance as the last banner falls.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

